const nitEmisor = String($input.first().json.query.nitEmisor || '').replace(/\D/g, '');
if (!nitEmisor) {
  throw new Error('Falta el parámetro nitEmisor en la consulta.');
}
return [{ json: { nitEmisor } }];

// Consulta por partes: si el panel vuelve a preguntar trae jobId/location (solo letras, números, - y _).
const _qp = $('Webhook: listar pagadores').first().json.query || {};
const _jobId = String(_qp.jobId || '').replace(/[^A-Za-z0-9_-]/g, '');
const _location = String(_qp.location || '').replace(/[^A-Za-z0-9-]/g, '') || 'us-east1';
const nitEmisor = $input.first().json.nitEmisor;

const columnas = [
  'nit_cliente', 'razon_social', 'disponible_total', 'estado_cupo_cliente',
  'anticipo', 'plazo', 'dias_mora', 'dias_mora_cliente',
  'aplica_rete_fuente', 'aplica_rete_ica', 'aplica_rete_iva',
  'nit_contraparte', 'razon_social_contraparte', 'viabilidad_contraparte',
  'disponible_contraparte', 'estado_cupo_contraparte', 'dias_mora_contraparte',
  'mecanismo_negociacion_contraparte', 'confirmacion_correo_pre_operacion', 'operatividad_pago_directo'
].join(', ');

const tabla = '`inlaid-stack-375114.analytics_data_products.mapping_rules`';

const bqQuery = 'SELECT ' + columnas + ' FROM ' + tabla +
  " WHERE nit_cliente = '" + nitEmisor + "'";

return [{ json: { jobId: _jobId, location: _location, nitEmisor, bqQuery } }];

// Consulta por partes: BigQuery aún no termina -> el panel vuelve a preguntar con este jobId.
const _r = $input.first().json || {};
if (_r.jobComplete === false && _r.jobReference && _r.jobReference.jobId) {
  return [{ json: { pendiente: true, jobId: _r.jobReference.jobId, location: _r.jobReference.location || 'us-east1' } }];
}
const resp = $input.first().json;
const fields = (resp.schema && resp.schema.fields) || [];
const rawRows = resp.rows || [];

const rows = rawRows.map(row => {
  const obj = {};
  row.f.forEach((cell, i) => { obj[fields[i].name] = cell.v; });
  return obj;
});

if (!rows.length) {
  return [{ json: { encontrado: false, emisor: null, pagadores: [] } }];
}

// 'plazo'/'plazo_2' llegan como texto tipo "90 días": se extrae el número.
function parsePlazo(v){
  if (v == null) return 0;
  const m = String(v).match(/\d+/);
  return m ? Number(m[0]) : 0;
}
// 'anticipo'/'anticipo_2' pueden llegar como fracción (0.95) o como porcentaje (95).
// Si es <= 1, se asume fracción y se multiplica por 100.
function parseAnticipo(v){
  const n = Number(v);
  if (!n) return 0;
  return n <= 1 ? n * 100 : n;
}

// Campos según la calculadora-mapeo de Álvaro. null = sin dato en el mapeo (esa regla no se valida).
function numOrNull(v){ return (v === null || v === undefined || v === '') ? null : Number(v); }

// Días de mora del cliente: la tabla trae dias_mora y dias_mora_cliente; se toma el mayor.
function moraCliente(r){
  const vals = [r.dias_mora, r.dias_mora_cliente].map(v => (v === null || v === undefined || v === '') ? null : Number(v)).filter(v => v !== null && isFinite(v));
  return vals.length ? Math.max(...vals) : null;
}
// Retenciones del cliente (base de Catalina): SI/NO, true/false o 1/0. null = sin dato (el comercial la marca a mano).
function aplica(v){
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim().normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
  if (['si', 's', 'true', '1', 'aplica', 'yes', 'x'].includes(s)) return true;
  if (['no', 'n', 'false', '0', 'no aplica'].includes(s)) return false;
  return null;
}

const emisor = {
  nit: rows[0].nit_cliente,
  razon_social: rows[0].razon_social || '',
  cupoDisponible: numOrNull(rows[0].disponible_total),
  estadoCupo: rows[0].estado_cupo_cliente || null,
  anticipoPactado: rows[0].anticipo == null ? null : parseAnticipo(rows[0].anticipo),
  plazoPactado: rows[0].plazo == null ? null : parsePlazo(rows[0].plazo),
  diasMora: moraCliente(rows[0]),
  retenciones: {
    reteFuente: aplica(rows[0].aplica_rete_fuente),
    reteIca: aplica(rows[0].aplica_rete_ica),
    reteIva: aplica(rows[0].aplica_rete_iva)
  }
};

const pagadores = rows
  .filter(r => r.nit_contraparte)
  .map(r => ({
    nit: r.nit_contraparte,
    razon_social: r.razon_social_contraparte || '',
    viabilidad: r.viabilidad_contraparte || '',
    cupoDisponible: numOrNull(r.disponible_contraparte),
    estadoCupo: r.estado_cupo_contraparte || null,
    diasMora: Number(r.dias_mora_contraparte) || 0,
    // Reglas de la contraparte que se llevan a HubSpot (texto tal cual viene del mapeo, sin espacios sobrantes).
    mecanismoNegociacion: r.mecanismo_negociacion_contraparte ? String(r.mecanismo_negociacion_contraparte).trim() : null,
    confirmacionCorreo: r.confirmacion_correo_pre_operacion ? String(r.confirmacion_correo_pre_operacion).trim() : null,
    pagoDirecto: r.operatividad_pago_directo ? String(r.operatividad_pago_directo).trim() : null
  }));

return [{ json: { encontrado: true, emisor, pagadores } }];
